def first_sorted_index(values, target):
    lo = 0
    hi = len(values)
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if values[mid] < target:
            lo = mid + 1
        else:
            hi = mid
    if lo < len(values) and values[lo] == target:
        return lo
    return -1

print(first_sorted_index([1, 3, 3, 7, 9], 3))
print(first_sorted_index([1, 3, 3, 7, 9], 4))
print(first_sorted_index([], 3))

def binary_first(values, target):
    lo, hi = 0, len(values)
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if values[mid] < target:
            lo = mid + 1
        else:
            hi = mid
    if lo < len(values) and values[lo] == target:
        return lo
    return -1

print(binary_first([1, 3, 3, 7], 3))
print(binary_first([1, 3, 7], 4))
print(binary_first([], 3))

def binary_in_range(values, target, lo, hi):
    if lo < 0 or lo > hi or hi > len(values):
        raise ValueError("invalid range")
    end = hi
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if values[mid] < target:
            lo = mid + 1
        else:
            hi = mid
    if lo < end and values[lo] == target:
        return lo
    return -1

print(binary_in_range([1, 3, 3, 7], 3, 2, 4))
print(binary_in_range([1, 3], 3, 0, 1))
print(binary_in_range([1, 3], 3, 1, 1))
try:
    binary_in_range([1], 1, 0, 2)
except ValueError:
    print("ValueError")
